import React, { useEffect, useState } from 'react';
import api from '../services/api';
import { useNotification } from '../contexts/NotificationContext';
import { FileUp, Upload } from 'lucide-react';

export default function ProfessorMateriais() {
  const [lista, setLista] = useState([]);
  const [disciplinas, setDisciplinas] = useState([]);
  const [form, setForm] = useState({ titulo: '', turma_id: '', disciplina_id: '', arquivo: null });
  const [erro, setErro] = useState('');
  const [ok, setOk] = useState('');
  const [saving, setSaving] = useState(false);
  const { success, error } = useNotification();

  const carregar = () => {
    api.get('/professor/materiais').then(r => setLista(r.data)).catch(() => setErro('Erro ao carregar materiais.'));
  };

  useEffect(() => {
    carregar();
    api.get('/professor/minhas-disciplinas').then(r => setDisciplinas(r.data)).catch(() => {});
  }, []);

  const turmasUnicas = [...new Map(disciplinas.map(d => [d.turma_id, { id: d.turma_id, nome: d.turma_nome }])).values()];
  const turmaNome = turmasUnicas.find(t => String(t.id) === String(form.turma_id))?.nome;
  const disciplinaNome = disciplinas.find(d => String(d.id) === String(form.disciplina_id))?.nome;

  const enviar = async (e) => {
    e.preventDefault();
    if (!form.arquivo) return setErro('Seleccione um ficheiro (PDF, vídeo ou imagem).');
    setSaving(true);
    setErro('');
    const fd = new FormData();
    fd.append('arquivo', form.arquivo);
    fd.append('titulo', form.titulo);
    if (form.turma_id) fd.append('turma_id', form.turma_id);
    if (form.disciplina_id) fd.append('disciplina_id', form.disciplina_id);
    try {
      await api.post('/professor/materiais', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      const destino = form.turma_id ? `para a turma ${turmaNome || form.turma_id}` : 'de forma geral';
      const detalheDisc = disciplinaNome ? ` (${disciplinaNome})` : '';
      success(`Material publicado ${destino}${detalheDisc}. Os alunos receberão notificação.`);
      setForm({ titulo: '', turma_id: '', disciplina_id: '', arquivo: null });
      carregar();
    } catch (err) {
      const message = err.response?.data?.message || 'Erro ao publicar.';
      setErro(message);
      error(message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="page-container">
      <div className="page-header">
        <h2><FileUp size={22} style={{ verticalAlign: 'middle', marginRight: 8 }} />Materiais didácticos</h2>
        <p style={{ color: 'var(--cinza)' }}>Partilhe PDF, vídeo ou imagens com as suas turmas.</p>
      </div>
      {erro && (
        <div className="alert alert-error" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span>{erro}</span>
          <button type="button" className="alert-close" onClick={() => setErro('')}>×</button>
        </div>
      )}
      {ok && (
        <div className="alert alert-success" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span>{ok}</span>
          <button type="button" className="alert-close" onClick={() => setOk('')}>×</button>
        </div>
      )}
      <div className="card" style={{ marginBottom: '1.5rem' }}>
        <form onSubmit={enviar}>
          <div className="form-group">
            <label className="form-label">Título</label>
            <input className="form-control" value={form.titulo} onChange={e => setForm({ ...form, titulo: e.target.value })} required />
          </div>
          <div className="form-row">
            <div className="form-group">
              <label className="form-label">Turma</label>
              <select className="form-control form-select" value={form.turma_id} onChange={e => setForm({ ...form, turma_id: e.target.value, disciplina_id: '' })}>
                <option value="">Todas / geral</option>
                {turmasUnicas.map(t => <option key={t.id} value={t.id}>{t.nome}</option>)}
              </select>
            </div>
            <div className="form-group">
              <label className="form-label">Disciplina</label>
              <select className="form-control form-select" value={form.disciplina_id} onChange={e => setForm({ ...form, disciplina_id: e.target.value })} disabled={!form.turma_id}>
                <option value="">—</option>
                {disciplinas.filter(d => !form.turma_id || String(d.turma_id) === String(form.turma_id)).map(d => (
                  <option key={d.disciplina_id} value={d.disciplina_id}>{d.disciplina_nome}</option>
                ))}
              </select>
            </div>
          </div>
          <div className="form-group">
            <label className="form-label">Ficheiro *</label>
            <input type="file" className="form-control" accept=".pdf,.mp4,.webm,.mov,.jpg,.jpeg,.png,.webp,.doc,.docx" onChange={e => setForm({ ...form, arquivo: e.target.files?.[0] || null })} />
          </div>
          <button type="submit" className="btn btn-primary" disabled={saving}>
            <Upload size={16} /> {saving ? 'A enviar...' : 'Publicar material'}
          </button>
        </form>
      </div>
      <div className="card" style={{ padding: 0 }}>
        <table className="table">
          <thead><tr><th>Título</th><th>Turma</th><th>Disciplina</th><th>Tipo</th></tr></thead>
          <tbody>
            {lista.map(m => (
              <tr key={m.id}>
                <td><strong>{m.titulo}</strong></td>
                <td>{m.turma_nome || '—'}</td>
                <td>{m.disciplina_nome || '—'}</td>
                <td>{m.tipo}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
